def test_hidden_positive():
    out = solution.forward([1, 1], [[1, 0], [0, 1]], [0, 0], [[1, 1]], [0])
    assert abs(out - 0.8807970779778823) < 1e-9

def test_relu_clamps():
    out = solution.forward([-1, -1], [[1, 0], [0, 1]], [0, 0], [[1, 1]], [0])
    assert abs(out - 0.5) < 1e-12

def test_second_layer_bias():
    out = solution.forward([0, 0], [[1, 0], [0, 1]], [1, 2], [[1, 0]], [-0.5])
    assert abs(out - 0.6224593312018546) < 1e-9

