        solution.forward([1, 2], [[1, 0]], [0], [[1, 0]], [0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_output_range():
    out = solution.forward([1, -1], [[1, 2], [-1, 0]], [0, 1], [[1, 1]], [-0.5])
    assert 0.0 < out < 1.0
